'use client';
import {useState} from 'react';import {ActionForm} from '@/components/vendor-forms';import {saveHours} from '@/app/vendor/actions';
const days=['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'];type Hour={day_of_week:number;opens_at:string|null;closes_at:string|null;is_closed:boolean};
export function HoursForm({hours}:{hours:Hour[]}){const initial=Array.from({length:7},(_,day)=>{const row=hours.find(item=>item.day_of_week===day);return{open:row?!row.is_closed:true,opens:row?.opens_at?.slice(0,5)??'11:00',closes:row?.closes_at?.slice(0,5)??'23:00'}});const[values,setValues]=useState(initial);function copyMonday(){const monday=values[1];setValues(values.map((value,index)=>index===0?value:{...monday}))}return <ActionForm action={saveHours} submitLabel="Enregistrer les horaires"><section className="vendor-card"><div className="card-head"><div><h2>Ma semaine</h2><p className="muted">Fermez un jour avec l’interrupteur.</p></div><button type="button" className="btn btn-outline" onClick={copyMonday}>Copier le lundi</button></div><div className="hours-list">{values.map((row,day)=><div key={day} className={row.open?'hour-row':'hour-row closed'}><strong>{days[day]}</strong><label className="switch"><input type="checkbox" name={`open_${day}`} checked={row.open} onChange={event=>setValues(current=>current.map((item,index)=>index===day?{...item,open:event.target.checked}:item))}/><span/></label>{row.open?<div><input aria-label={`Ouverture ${days[day]}`} type="time" name={`opens_${day}`} value={row.opens} onChange={event=>setValues(current=>current.map((item,index)=>index===day?{...item,opens:event.target.value}:item))}/><b>→</b><input aria-label={`Fermeture ${days[day]}`} type="time" name={`closes_${day}`} value={row.closes} onChange={event=>setValues(current=>current.map((item,index)=>index===day?{...item,closes:event.target.value}:item))}/></div>:<em>Fermé</em>}</div>)}</div></section></ActionForm>}
